package com.bank.size;

import java.util.logging.Logger;

// Mimics org.apache.spark.util.SizeEstimator: account for object headers, references,
// alignment padding, and String contents. Returns an estimate in bytes.
class JvmSizeEstimator {
    private static final Logger log = Logger.getLogger(JvmSizeEstimator.class.getName());

    private static final int OBJECT_HEADER = 16;   // typical 64-bit header
    private static final int REF = 8;              // reference size (no compressed oops)
    private static final int ALIGNMENT = 8;        // objects aligned to 8 bytes

    // Estimate bytes for one Account instance and everything it references.
    long estimate(Account a) {
        // Account object: header + 3 references (3 strings) + 1 long
        long base = OBJECT_HEADER + (3L * REF) + 8L;
        base = align(base);
        // Each String: header + ref to char[] + hash int + the char[] itself.
        long strings = stringBytes(a.accountId) + stringBytes(a.holderName) + stringBytes(a.branch);
        long total = base + strings;
        log.fine(() -> "Account " + a.accountId + " estimated at " + total + " bytes in memory");
        return total;
    }

    private long stringBytes(String s) {
        long charsArray = OBJECT_HEADER + 4L /*length*/ + (long) s.length() * 2; // UTF-16 chars
        long stringObj = OBJECT_HEADER + REF /*value ref*/ + 4L /*hash*/;
        return align(stringObj) + align(charsArray);
    }

    private long align(long bytes) {
        long rem = bytes % ALIGNMENT;
        return rem == 0 ? bytes : bytes + (ALIGNMENT - rem);
    }
}
