package com.bank.size;

import java.util.List;
import java.util.logging.Logger;

// Decides broadcast vs shuffle using an estimated in-memory size, a margin, and a ceiling.
class BroadcastAdvisor {
    private static final Logger log = Logger.getLogger(BroadcastAdvisor.class.getName());

    private final JvmSizeEstimator estimator;
    private final long ceilingBytes;
    private final double safetyMargin;
    private final int sampleRows;

    BroadcastAdvisor(JvmSizeEstimator estimator, long ceilingBytes, double safetyMargin, int sampleRows) {
        this.estimator = estimator;
        this.ceilingBytes = ceilingBytes;
        this.safetyMargin = safetyMargin;
        this.sampleRows = sampleRows;
    }

    // Returns true if the table is safe to broadcast.
    boolean shouldBroadcast(String tableName, List<Account> table) {
        int sampleSize = Math.min(sampleRows, table.size());
        long sampleBytes = 0;
        for (int i = 0; i < sampleSize; i++) sampleBytes += estimator.estimate(table.get(i));

        double perRow = (double) sampleBytes / sampleSize;
        long estimatedTotal = Math.round(perRow * table.size() * safetyMargin);

        boolean broadcast = estimatedTotal <= ceilingBytes;
        log.info(() -> String.format(
            "%s: rows=%,d  perRow~%.0fB  estTotal(w/margin)=%,dB  ceiling=%,dB  → %s",
            tableName, table.size(), perRow, estimatedTotal, ceilingBytes,
            broadcast ? "BROADCAST (safe)" : "SHUFFLE JOIN (too big to broadcast)"));
        if (!broadcast) {
            log.warning(() -> tableName + " exceeds broadcast ceiling — forcing a broadcast here would risk OOM");
        }
        return broadcast;
    }
}
