package com.bank.size;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class SizeDemo {
    private static final Logger log = Logger.getLogger(SizeDemo.class.getName());

    public static void main(String[] args) {
        JvmSizeEstimator estimator = new JvmSizeEstimator();
        BroadcastAdvisor advisor = new BroadcastAdvisor(estimator, 52_428_800L, 1.5, 100);

        // Small reference table: ~500 branch codes → should broadcast.
        List<Account> branches = new ArrayList<>();
        for (int i = 0; i < 500; i++) {
            branches.add(new Account("BR" + i, "Branch Manager " + i, "City-" + i, 0L));
        }
        advisor.shouldBroadcast("branch_reference", branches);

        // Large table: 2,000,000 accounts → should NOT broadcast.
        List<Account> accounts = new ArrayList<>();
        for (int i = 0; i < 2_000_000; i++) {
            accounts.add(new Account("ACCT" + i, "Customer Fullname " + i, "Branch-Mumbai-Fort", 100000L + i));
        }
        advisor.shouldBroadcast("all_accounts", accounts);

        // Show the single-object estimate (what SizeEstimator.estimate returns).
        long one = estimator.estimate(new Account("SAV2001", "Rajesh Kumar", "Mumbai-Fort", 100000000L));
        log.info(() -> "Single Account (Rajesh) estimated in-memory size = " + one + " bytes");
    }
}
